package compose

import (
	"github.com/ui8kit/codegen/generated/templ/ui/button"
	"github.com/ui8kit/codegen/generated/templ/ui/icon"
)

// ThemeToggleProps: Button + Lucide icons (data-ui8kit="theme-toggle").
type ThemeToggleProps struct {
	Variant   string
	Size      string
	AriaLabel string
	button.ButtonProps
}

func themeToggleInner(p ThemeToggleProps) button.ButtonProps {
	in := p.ButtonProps
	in.Type = "button"
	in.Class = Join(Rc("themetoggle", map[string]string{"variant": p.Variant, "size": p.Size}), p.ButtonProps.Class)
	fixed := map[string]string{"data-ui8kit": "theme-toggle", "aria-pressed": "false", "aria-label": Or(p.AriaLabel, "Dark mode")}
	in.Attrs = WithAttrs(in.Attrs, fixed)
	return in
}

// ThemeToggle renders the button with its Lucide icons.
templ ThemeToggle(p ThemeToggleProps) {
	@button.Button(themeToggleInner(p)) {
		@icon.Icon(icon.IconProps{Class: "hidden size-5 dark:block"}) {
			@templ.Raw(lucideSun)
		}
		@icon.Icon(icon.IconProps{Class: "block size-5 dark:hidden"}) {
			@templ.Raw(lucideMoon)
		}
	}
}
